/* World Landmarks set additions — cards appended after world-landmarks.js.
   (world-landmarks.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'world-landmarks.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('world-landmarks');
  if (!S) return;
  var extra = [{"name":"Hadrian's Wall","rarity":"uncommon","id":"hadrians-wall","subtitle":"Ancient Site","details":"Built from AD 122 across northern England, Hadrian's Wall was Rome's frontier barrier of stone ramparts, milecastles, forts and a deep defensive ditch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hadrian%27s%20Wall%20%2C%20Steel%20Rigg%20-%20geograph.org.uk%20-%207235395.jpg?width=1024"},{"name":"Pont du Gard","rarity":"uncommon","id":"pont-du-gard","subtitle":"Ancient Site","details":"A Roman aqueduct bridge in southern France built around AD 50, the Pont du Gard carries water across the Gardon River on three tiers of limestone arches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pont_du_Gard_BLS.jpg?width=1024"},{"name":"El Jem Amphitheatre","rarity":"uncommon","id":"el-jem-amphitheatre","subtitle":"Ancient Site","details":"Built in Tunisia around AD 238, the amphitheatre of El Jem is a freestanding Roman oval of golden sandstone, modelled on the Colosseum in Rome.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Amphitheatre_of_El_Jem%2C_built_around_AD_238_in_Thysdrus_in_Africa_Proconsularis%2C_the_estimated_capacity_is_35%2C000%2C_Tunisia_-_52717762494.jpg?width=1024"},{"name":"Leptis Magna","rarity":"uncommon","id":"leptis-magna","subtitle":"Ancient Site","details":"A Punic and Roman port city in Libya, Leptis Magna was lavishly rebuilt in marble and limestone by its native son, the emperor Septimius Severus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leptis_Magna_%2829%29_%288288918733%29.jpg?width=1024"},{"name":"Nan Madol","rarity":"uncommon","id":"nan-madol","subtitle":"Ancient Site","details":"Built of stacked basalt logs on artificial islets off Pohnpei, Nan Madol was a stone city of royal tombs and ritual houses raised from about AD 1180.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nan_madol.jpg?width=1024"},{"name":"Cahokia Mounds","rarity":"uncommon","id":"cahokia-mounds","subtitle":"Ancient Site","details":"Near the Mississippi River, Cahokia was North America's largest pre-Columbian city, centred on Monks Mound, the biggest earthen pyramid north of Mexico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monks_Mound_-_Summer_2024.jpg?width=1024"},{"name":"Chaco Canyon","rarity":"uncommon","id":"chaco-canyon","subtitle":"Ancient Site","details":"Between about AD 850 and 1150, Ancestral Pueblo builders raised Chaco Canyon's great houses of sandstone and timber, linked by a network of roads.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chaco%20Canyon-Pueblo%20Bonito-12-Felsen-1982-gje.jpg?width=1024"},{"name":"Serpent Mound","rarity":"uncommon","id":"serpent-mound","subtitle":"Ancient Site","details":"A sinuous earthen snake over 400 metres long in Ohio, the Great Serpent Mound was shaped along a bluff above Brush Creek by Indigenous builders.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Serpent%20Mound%20%28aerial%20view%29.jpg?width=1024"},{"name":"Poverty Point","rarity":"uncommon","id":"poverty-point","subtitle":"Ancient Site","details":"Built in Louisiana between about 1700 and 1100 BC, Poverty Point's sweeping concentric earthen ridges and mounds formed a vast hunter-gatherer settlement.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mound%20A%20at%20the%20Monumental%20Earthworks%20Poverty%20Point%20World%20Heritage%20Site.jpg?width=1024"},{"name":"Hagar Qim","rarity":"uncommon","id":"hagar-qim","subtitle":"Ancient Site","details":"Built of globigerina limestone on Malta around 3600 BC, Hagar Qim's megalithic temple chambers rank among the oldest freestanding stone buildings on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Facade_Hagar_Qim.jpg?width=1024"},{"name":"Tarxien Temples","rarity":"uncommon","id":"tarxien-temples","subtitle":"Ancient Site","details":"Built on Malta between about 3600 and 2500 BC, the Tarxien Temples preserve carved stone altars, screens and reliefs of animals and spirals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Malta_-_Tarxien_-_Triq_it-Tempji_Neolitici_-_Temples_26_ies.jpg?width=1024"},{"name":"Skara Brae","rarity":"uncommon","id":"skara-brae","subtitle":"Ancient Site","details":"Buried by sand for millennia in Orkney, Skara Brae is a Neolithic village of stone houses built around 3180 BC, complete with stone beds and dressers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2018_07_12_Schottland_%2894%29.jpg?width=1024"},{"name":"Ring of Brodgar","rarity":"uncommon","id":"ring-of-brodgar","subtitle":"Ancient Site","details":"A Neolithic stone circle and henge in Orkney, the Ring of Brodgar's tall slabs stand on a narrow isthmus between the Lochs of Stenness and Harray.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ring_of_Brodgar%2C_Orkney.jpg?width=1024"},{"name":"Callanish Stones","rarity":"uncommon","id":"callanish-stones","subtitle":"Ancient Site","details":"Raised on the Isle of Lewis around 2900 BC, the Callanish Stones form a cross-shaped setting of Lewisian gneiss pillars around a central circle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Callanish_at_sunset_-_geograph.org.uk_-_820680.jpg?width=1024"},{"name":"Bandelier National Monument","rarity":"uncommon","id":"bandelier-national-monument","subtitle":"Ancient Site","details":"Ancestral Pueblo families carved homes into the soft volcanic tuff of Frijoles Canyon in New Mexico, farming its floor from the 12th century onward.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bandelier_Kiva.jpg?width=1024"},{"name":"Hovenweep","rarity":"uncommon","id":"hovenweep","subtitle":"Ancient Site","details":"Built around AD 1200 by Ancestral Pueblo masons, Hovenweep's square, round and D-shaped stone towers guard canyon springs on the Colorado-Utah border.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hovenweep_in_snow.jpg?width=1024"},{"name":"Aqueduct of Segovia","rarity":"uncommon","id":"aqueduct-of-segovia","subtitle":"Ancient Site","details":"A Roman aqueduct built around AD 50, Segovia's granite arcade marches double-tiered arches through the Spanish city, its blocks laid without mortar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aqueduct_of_Segovia_08.jpg?width=1024"},{"name":"Baths of Caracalla","rarity":"uncommon","id":"baths-of-caracalla","subtitle":"Ancient Site","details":"Opened in Rome in AD 216, the Baths of Caracalla were a marble-lined leisure complex of pools, gyms and libraries set within vast brick and concrete halls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baths_of_Caracalla%2C_facing_Caldarium.jpg?width=1024"},{"name":"Royal Albert Hall","rarity":"uncommon","id":"royal-albert-hall","subtitle":"Hall","details":"Opened in 1871 in South Kensington, London, this circular concert hall of red brick and terracotta was built in memory of Prince Albert.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Royal%20Albert%20Hall%2C%20London%20-%20Nov%202012.jpg?width=1024"},{"name":"Carnegie Hall","rarity":"uncommon","id":"carnegie-hall","subtitle":"Hall","details":"Andrew Carnegie funded this New York concert hall, opened in 1891 on Seventh Avenue, praised ever since for the acoustics of its main auditorium.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carnegie%20Hall%20-%20Full%20%2848155558466%29.jpg?width=1024"},{"name":"Bolshoi Theatre","rarity":"uncommon","id":"bolshoi-theatre","subtitle":"Hall","details":"Moscow's grand neoclassical theatre, opened in 1825 and crowned by a quadriga of Apollo, is home to one of the world's historic ballet companies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moscow%20-%20Bolshoi%20Theatre%20from%20Teatralnaya%20Square%202024-5%20v4.jpg?width=1024"},{"name":"Palais Garnier","rarity":"uncommon","id":"palais-garnier","subtitle":"Hall","details":"Charles Garnier's opulent Paris opera house, opened in 1875, wraps its auditorium in marble, gilding and a grand staircase of sweeping curves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paris%20Opera%20House%2C%20Palais%20Garnier.jpeg?width=1024"},{"name":"La Scala","rarity":"uncommon","id":"la-scala","subtitle":"Hall","details":"Milan's Teatro alla Scala, opened in 1778 on the site of a church, seats its audiences in a horseshoe of red-and-gold boxes facing a deep stage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Front%20facade%20of%20La%20Scala%2C%20Milan.jpg?width=1024"},{"name":"Harpa Concert Hall","rarity":"uncommon","id":"harpa-concert-hall","subtitle":"Hall","details":"Opened in 2011 on Reykjavik's harbour, Harpa wraps its concert halls in a glass facade of geometric panels inspired by Iceland's basalt landscape.","image":"https://thumb.wikimedia.org/wikipedia/en/thumb/d/df/Harpa_Concert_Hall%2C_Reykjavik.jpg/1280px-Harpa_Concert_Hall%2C_Reykjavik.jpg"},{"name":"Elbphilharmonie","rarity":"uncommon","id":"elbphilharmonie","subtitle":"Building","details":"Hamburg's concert hall, opened in 2017, sets a wave-like glass structure atop a brick warehouse on a point in the Elbe River harbour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elbphilharmonie%2C%20Hamburg.jpg?width=1024"},{"name":"Walt Disney Concert Hall","rarity":"uncommon","id":"walt-disney-concert-hall","subtitle":"Hall","details":"Frank Gehry's Los Angeles concert hall, opened in 2003, folds stainless steel sails around the home stage of the Los Angeles Philharmonic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Image-Disney%20Concert%20Hall%20by%20Carol%20Highsmith%20edit.jpg?width=1024"},{"name":"Casa Mila","rarity":"uncommon","id":"casa-mila","subtitle":"Building","details":"Antoni Gaudi's Casa Mila, finished in 1912 in Barcelona, ripples in undulating stone, with sculpted chimneys standing guard across its roof terrace.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%2C%20Ayats%20Bravo%20I%20City%20%C4%8D.%202563%20Casa%20Mil%C3%A0.jpg?width=1024"},{"name":"Casa Batllo","rarity":"uncommon","id":"casa-batllo","subtitle":"Building","details":"Remodelled by Antoni Gaudi in 1904, this Barcelona house shimmers with mosaic scales, mask-like balconies and a roof shaped like a dragon's back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Exterior%20of%20Casa%20Batl%C3%B3%20-%20Barcelona%202014.jpg?width=1024"},{"name":"Palau de la Musica Catalana","rarity":"uncommon","id":"palau-de-la-musica-catalana","subtitle":"Building","details":"Built in 1908 in Barcelona, this concert hall by Lluis Domenech i Montaner glows with stained glass beneath a great central skylight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barcelona%20-%20Palau%20de%20la%20M%C3%BAsica%20Catalana%20%2832%29.jpg?width=1024"},{"name":"Atomium","rarity":"uncommon","id":"atomium","subtitle":"Building","details":"Built for the Brussels World's Fair of 1958, the Atomium joins nine steel spheres in the shape of an iron crystal magnified 165 billion times.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atomium%2C%20Bruselas%2C%20B%C3%A9lgica%2C%202021-12-15%2C%20DD%20148-150%20HDR.jpg?width=1024"},{"name":"Heydar Aliyev Center","rarity":"uncommon","id":"heydar-aliyev-center","subtitle":"Building","details":"Zaha Hadid's cultural centre in Baku, opened in 2012, flows in one continuous white wave of curves without a single straight line in its shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heydar%20Aliyev%20Center%2C%20Baku%20-%20HyderAliyevCenter8319.jpg?width=1024"},{"name":"Pompidou Centre","rarity":"uncommon","id":"pompidou-centre","subtitle":"Building","details":"Opened in 1977 in Paris, this arts centre turned itself inside out, putting its pipes, ducts and escalators colourfully on the outside walls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centre%20Pompidou%20%40%20Beaubourg%20%40%20Paris%20%2815448205062%29.jpg?width=1024"},{"name":"Lloyd's Building","rarity":"uncommon","id":"lloyds-building","subtitle":"Building","details":"Completed in 1986 in the City of London, this insurance headquarters stacks its lifts, ducts and services around the outside of a concrete frame.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/London%20-%20The%20Lloyd%27s%20building%20%281%29.jpg?width=1024"},{"name":"St. Pancras Station","rarity":"uncommon","id":"st-pancras-station","subtitle":"Station","details":"London's St Pancras station, opened in 1868, pairs a Gothic Revival hotel front with a vast single-span train shed engineered by William Barlow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St%20Pancras%20Renaissance%20Hotel%20and%20Station%20Facade-6333.jpg?width=1024"},{"name":"Antwerp Central Station","rarity":"uncommon","id":"antwerp-central-station","subtitle":"Station","details":"Opened in 1905, Antwerp's central station stacks its tracks in levels beneath a grand stone hall capped by a dome of iron and glass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antwerp%2C%20BE%20%28DSC%200166%29%20Antwerpen-Centraal%20railway%20station%20main%20hall.jpg?width=1024"},{"name":"Chhatrapati Shivaji Terminus","rarity":"uncommon","id":"chhatrapati-shivaji-terminus","subtitle":"Station","details":"This Mumbai railway terminus, completed in 1887 as Victoria Terminus, blends Victorian Gothic stone with Indian carving and a great central dome.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mumbai%20-%20Chhatrapati%20Shivaji%20Terminus%20Frontside%20-%202.jpg?width=1024"},{"name":"Flinders Street Station","rarity":"uncommon","id":"flinders-street-station","subtitle":"Station","details":"Melbourne's main station, opened in 1910 in yellow Edwardian style, is famed for the row of clocks above its Swanston Street entrance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flinders%20Street%20Station%20Melbourne%20March%202021%20cropped.jpg?width=1024"},{"name":"Dunedin Station","rarity":"uncommon","id":"dunedin-station","subtitle":"Station","details":"Opened in 1906 in Dunedin, New Zealand, this Flemish Renaissance station of dark basalt and white limestone is richly trimmed with royal tiles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dunedin%20Railway%20Station%20Full%20Exterior.jpg?width=1024"},{"name":"Grant's Tomb","rarity":"common","id":"grants-tomb","subtitle":"Memorial","details":"Completed in New York in 1897, this granite mausoleum on the Hudson holds Ulysses S. Grant and his wife Julia, modelled on Napoleon's tomb in Paris.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/General_Grant_National_Memorial_New_York_November_2016_003.jpg?width=1024"},{"name":"San Jacinto Monument","rarity":"common","id":"san-jacinto-monument","subtitle":"Monument","details":"Texas raised this 172-metre limestone obelisk in 1939 near Houston, crowned by a 220-tonne star, marking its 1836 victory over Mexico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/San_Jacinto_Monument.jpg?width=1024"},{"name":"Perry's Victory Memorial","rarity":"common","id":"perrys-victory-memorial","subtitle":"Memorial","details":"Rising 107 metres over Lake Erie at Put-in-Bay, this pink granite column, completed in 1915, honours Oliver Hazard Perry's War of 1812 victory.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Memorial_and_Park_Grounds_%2864dd534f-155d-4519-3eb9-a9e422020e08%29.jpg?width=1024"},{"name":"Bennington Battle Monument","rarity":"common","id":"bennington-battle-monument","subtitle":"Monument","details":"Vermont's 93-metre blue-grey limestone obelisk, finished in 1889, marks the 1777 Battle of Bennington and overlooks three states from its top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bennington_Battle_Monument_in_2026.jpg?width=1024"},{"name":"Yorktown Victory Monument","rarity":"common","id":"yorktown-victory-monument","subtitle":"Monument","details":"Erected in Virginia in 1881-84, this 29-metre granite column topped by Victory marks the 1781 surrender that ended the Revolutionary War.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yorktown_monument1.jpg?width=1024"},{"name":"The Minute Man","rarity":"common","id":"the-minute-man","subtitle":"Statue","details":"Daniel Chester French sculpted this bronze farmer-soldier in 1874 for Concord, Massachusetts, rifle in hand, honouring the militiamen of April 1775.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/French%27s_Concord_Minuteman_statue.jpg?width=1024"},{"name":"The Little Mermaid","rarity":"common","id":"the-little-mermaid","subtitle":"Statue","details":"Unveiled on Copenhagen's harbour rocks in 1913, Edvard Eriksen's bronze mermaid sits 1.25 metres tall, from Hans Christian Andersen's fairy tale.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Copenhagen_-_the_little_mermaid_statue_-_2013.jpg?width=1024"},{"name":"Manneken Pis","rarity":"common","id":"manneken-pis","subtitle":"Statue","details":"This small bronze boy has filled a Brussels fountain since 1619; the city dresses Duquesnoy's statue in hundreds of costumes kept in a museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bruxelles_Manneken_Pis_cropped.jpg?width=1024"},{"name":"Merlion","rarity":"common","id":"merlion","subtitle":"Statue","details":"Singapore's Merlion, unveiled in 1972, joins a lion's head to a fish's body; the 8.6-metre statue spouts water from its mouth into Marina Bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Merlion%20Statue%20at%20Merlion%20Park%2C%20Singapore%20%28Ank%20Kumar%20%29%2001.jpg?width=1024"},{"name":"Charging Bull","rarity":"common","id":"charging-bull","subtitle":"Statue","details":"Arturo Di Modica cast this 3.2-tonne bronze bull and set it on Wall Street in 1989 as a symbol of financial strength; it stands at Bowling Green.","image":"https://en.wikipedia.org/wiki/Special:FilePath/Charging_Bull_statue.jpg?width=1024"},{"name":"Berlin Victory Column","rarity":"common","id":"berlin-victory-column","subtitle":"Monument","details":"Berlin's Victory Column, completed in 1873, rises 67 metres over the Tiergarten, its gilded Victoria above a column built from captured cannon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20-%20Siegess%C3%A4ule1.jpg?width=1024"},{"name":"Alexander Column","rarity":"common","id":"alexander-column","subtitle":"Monument","details":"Raised in St. Petersburg in 1834, this polished red granite shaft stands 25.6 metres tall, honouring Alexander I and the victory over Napoleon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/00_0047_Alexander_Column_on_Palace_Square_in_Saint_Petersburg.jpg?width=1024"},{"name":"Vendome Column","rarity":"common","id":"vendome-column","subtitle":"Monument","details":"Modelled on Trajan's Column and finished in Paris in 1810, this 44-metre column is wrapped in bronze reliefs cast from cannon taken at Austerlitz.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Place%20Vend%C3%B4me%20-%20Colonne%20Vend%C3%B4me%20%28Paris%29.jpg?width=1024"},{"name":"July Column","rarity":"common","id":"july-column","subtitle":"Monument","details":"Paris's July Column, finished in 1840, rises 47 metres over the Bastille site, honouring the Parisians who fell in the July Revolution of 1830.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colonne_de_Juillet_972.jpg?width=1024"},{"name":"Arc de Triomf","rarity":"common","id":"arc-de-triomf","subtitle":"Monument","details":"Josep Vilaseca designed Barcelona's red brick Arc de Triomf as the gateway to the 1888 world's fair, its friezes celebrating the host city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Barcelona_-_Arc_de_Triomf_%282%29.JPG?width=1024"},{"name":"Shaftesbury Memorial Fountain","rarity":"common","id":"shaftesbury-memorial-fountain","subtitle":"Memorial","details":"Unveiled in Piccadilly Circus in 1893, Alfred Gilbert's fountain lifts a winged aluminium archer, Anteros, above bronze dolphins and shells.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fuente_Eros%2C_Piccadilly_Circus%2C_Londres%2C_Inglaterra%2C_2014-08-11%2C_DD_159.JPG?width=1024"},{"name":"Sigismund's Column","rarity":"common","id":"sigismunds-column","subtitle":"Monument","details":"Warsaw's Sigismund's Column, raised in 1644, is a 22-metre column honouring the king who moved Poland's capital to Warsaw in 1596.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kolumna_Zygmunta_III_Wazy%2CWarszawa.jpg?width=1024"},{"name":"National Memorial Arch","rarity":"common","id":"national-memorial-arch","subtitle":"Memorial","details":"Valley Forge's National Memorial Arch, dedicated in 1917, is a 49-metre granite arch modelled on Rome's Arch of Titus, honouring Washington's army.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/National_Memorial_Arch_at_Dusk.jpg?width=1024"},{"name":"Soldiers' National Monument","rarity":"common","id":"soldiers-national-monument","subtitle":"Monument","details":"Erected at Gettysburg in 1869, this granite monument honours the Union dead, ringed by figures of War, History, Industry, Plenty and Peace.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Solnatmon_gettysburg.jpg?width=1024"},{"name":"Guan Yu Statue","rarity":"common","id":"guan-yu-statue","subtitle":"Statue","details":"Unveiled in Jingzhou, China in 2016, this bronze statue of warrior god Guan Yu stands 58 metres tall, holding a glaive weighing over 130 tonnes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guan%20Yu%20Statue.jpg?width=1024"},{"name":"Lord Murugan Statue","rarity":"common","id":"lord-murugan-statue","subtitle":"Statue","details":"At Malaysia's Batu Caves since 2006, this gilded statue of Lord Murugan stands 42.7 metres tall, built from 350 tonnes of steel and concrete.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lord%20Muruga%20Batu%20Caves.jpg?width=800"},{"name":"Christ the Blessing","rarity":"common","id":"christ-the-blessing","subtitle":"Monument","details":"Consecrated in Manado, Indonesia in 2007, this 30-metre steel Christ leans forward at a tilt over the city, arms open above the Celebes Sea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yesus_Kase_Berkat_Manado.jpg?width=1024"},{"name":"Avukana Buddha","rarity":"common","id":"avukana-buddha","subtitle":"Statue","details":"Carved from a living granite cliff in Sri Lanka in the 5th century, this 14-metre standing Buddha still clings to the rock face behind it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buda_de_Avukana_-_03.jpg?width=1024"},{"name":"Shrine of Remembrance","rarity":"common","id":"shrine-of-remembrance","subtitle":"Monument","details":"Melbourne's Shrine of Remembrance, opened in 1934, is a stepped stone pyramid honouring Victoria's war dead, lit by a ray of sun each November 11.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shrine_of_Rememberance_%2811884180023%29.jpg?width=1024"},{"name":"Capilano Suspension Bridge","rarity":"common","id":"capilano-suspension-bridge","subtitle":"Bridge","details":"Vancouver's Capilano Suspension Bridge, first built in 1889, crosses the Capilano River canyon on a narrow pedestrian span 70 metres above the water.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/64/Capilano_Suspension_Bridge%2C_Vancouver%2C_Canada_%28July_2016%29_1.jpg/1280px-Capilano_Suspension_Bridge%2C_Vancouver%2C_Canada_%28July_2016%29_1.jpg"},{"name":"Kintai Bridge","rarity":"common","id":"kintai-bridge","subtitle":"Bridge","details":"Japan's Kintai Bridge, first built in 1673 at Iwakuni, crosses the Nishiki River on five wooden arches resting on stone piers, rebuilt with traditional joinery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iwakuni%2C%20ponte%20kintai-kyo%2C%2005.jpg?width=1024"},{"name":"Chengyang Bridge","rarity":"common","id":"chengyang-bridge","subtitle":"Bridge","details":"The Chengyang Bridge in Guangxi, China, built in 1912, is a covered wind-and-rain bridge of wood and stone, roofed with pavilions over the Linxi River.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/Dong-minority-bridge-1.jpg"},{"name":"Anji Bridge","rarity":"common","id":"anji-bridge","subtitle":"Bridge","details":"China's Anji Bridge, completed about 605 under the Sui dynasty, crosses the Xiao River as an early open-spandrel segmental stone arch bridge that survives.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/Zhaozhou_Bridge.jpg/1280px-Zhaozhou_Bridge.jpg"},{"name":"Pont d'Avignon","rarity":"common","id":"pont-davignon","subtitle":"Bridge","details":"The Pont d'Avignon, built from 1177 in southern France, once crossed the Rhone with 22 arches; four arches and a small chapel still stand on its bank.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/%22Sur_le_Pont_d%27Avignon_on_y_danse%22_is_the_famous_song%2C_but_now_we_see_only_many_tourist_just_standing_there_-_panoramio.jpg/1280px-%22Sur_le_Pont_d%27Avignon_on_y_danse%22_is_the_famous_song%2C_but_now_we_see_only_many_tourist_just_standing_there_-_panoramio.jpg"},{"name":"Magdeburg Water Bridge","rarity":"common","id":"magdeburg-water-bridge","subtitle":"Bridge","details":"Germany's Magdeburg Water Bridge, opened in 2003, is a navigable aqueduct carrying ships over the River Elbe, linking the Elbe-Havel and Mittelland canals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Magdeburg_Kanalbr%C3%BCcke_aerial_view_13.jpg/1280px-Magdeburg_Kanalbr%C3%BCcke_aerial_view_13.jpg"},{"name":"Banpo Bridge","rarity":"common","id":"banpo-bridge","subtitle":"Bridge","details":"Seoul's Banpo Bridge, completed in 1982, crosses the Han River as a double-deck girder bridge, fitted with the Moonlight Rainbow Fountain along its sides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/2011%EB%85%84_11%EC%9B%94_%EB%8C%80%ED%95%9C%EB%AF%BC%EA%B5%AD_%EC%84%9C%EC%9A%B8%ED%8A%B9%EB%B3%84%EC%8B%9C_%EB%AA%85%EC%86%8C_%28Seoul_best_attractions%29_%EB%8B%AC%EB%B9%9B%EB%AC%B4%EC%A7%80%EA%B0%9C%EB%B6%84%EC%88%981.jpg/1280px-2011%EB%85%84_11%EC%9B%94_%EB%8C%80%ED%95%9C%EB%AF%BC%EA%B5%AD_%EC%84%9C%EC%9A%B8%ED%8A%B9%EB%B3%84%EC%8B%9C_%EB%AA%85%EC%86%8C_%28Seoul_best_attractions%29_%EB%8B%AC%EB%B9%9B%EB%AC%B4%EC%A7%80%EA%B0%9C%EB%B6%84%EC%88%981.jpg"},{"name":"Helix Bridge","rarity":"common","id":"helix-bridge","subtitle":"Bridge","details":"Singapore's Helix Bridge, opened in 2010, is a pedestrian link across Marina Bay built as twin stainless-steel helix tubes inspired by the structure of DNA.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Double-Helix-Bridge.jpg?width=800"},{"name":"Henderson Waves Bridge","rarity":"common","id":"henderson-waves-bridge","subtitle":"Bridge","details":"Singapore's Henderson Waves, opened in 2008, is a pedestrian bridge of undulating steel and timber ribs, crossing above Henderson Road at 36 metres high.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/HendersonWaves-Singapore-externalview-20090220.jpg/1280px-HendersonWaves-Singapore-externalview-20090220.jpg"},{"name":"Langkawi Sky Bridge","rarity":"common","id":"langkawi-sky-bridge","subtitle":"Bridge","details":"Malaysia's Langkawi Sky Bridge, completed in 2005, is a curved pedestrian cable-stayed bridge suspended 660 metres above sea level on Mount Mat Cincang.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f8/Langkawi_sky_bridge.jpg"},{"name":"Rolling Bridge","rarity":"common","id":"rolling-bridge","subtitle":"Bridge","details":"London's Rolling Bridge at Paddington, designed by Thomas Heatherwick and completed in 2004, curls into an octagon to let boats pass the canal basin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/The_Rolling_Bridge_by_Thomas_Heatherwick%2C_Paddington_Basin2.jpg/1280px-The_Rolling_Bridge_by_Thomas_Heatherwick%2C_Paddington_Basin2.jpg"},{"name":"Seri Wawasan Bridge","rarity":"common","id":"seri-wawasan-bridge","subtitle":"Bridge","details":"Putrajaya's Seri Wawasan Bridge, opened in 2003, is an asymmetric cable-stayed bridge over Putrajaya Lake, its single leaning pylon shaped like a ship's sail.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Jambatan_Seri_Wawasan_4493633704_3cbff54de1.jpg/1280px-Jambatan_Seri_Wawasan_4493633704_3cbff54de1.jpg"},{"name":"Juscelino Kubitschek Bridge","rarity":"common","id":"juscelino-kubitschek-bridge","subtitle":"Bridge","details":"Brasilia's Juscelino Kubitschek Bridge, opened in 2002, crosses Lake Paranoa on three steel arches that alternate sides of its concrete deck as they rise.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Ponte_JK_ser%C3%A1_interditada_na_manh%C3%A3_de_domingo_%2819357314503%29.jpg/1280px-Ponte_JK_ser%C3%A1_interditada_na_manh%C3%A3_de_domingo_%2819357314503%29.jpg"},{"name":"Octavio Frias Bridge","rarity":"common","id":"octavio-frias-bridge","subtitle":"Bridge","details":"Sao Paulo's Octavio Frias de Oliveira Bridge, opened in 2008, carries two curved decks over the Pinheiros River from a single X-shaped concrete tower.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Ponte_estaiada_Octavio_Frias_-_Sao_Paulo.jpg/1280px-Ponte_estaiada_Octavio_Frias_-_Sao_Paulo.jpg"},{"name":"Samuel Beckett Bridge","rarity":"common","id":"samuel-beckett-bridge","subtitle":"Bridge","details":"Dublin's Samuel Beckett Bridge, designed by Santiago Calatrava and opened in 2009, crosses the River Liffey with cables recalling a harp lying on its side.","image":"https://upload.wikimedia.org/wikipedia/commons/7/74/Samuel_Beckett_Bridge_At_Sunset_Dublin_Ireland_%2897037639%29.jpeg"},{"name":"Zakim Bridge","rarity":"common","id":"zakim-bridge","subtitle":"Bridge","details":"Boston's Zakim Bridge, opened in 2003, carries Interstate 93 over the Charles River, its twin towers rising through a wide cable-stayed deck of ten lanes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Zakim_Bridge_and_railroad_bridge_Boston_P1010835.jpg/1280px-Zakim_Bridge_and_railroad_bridge_Boston_P1010835.jpg"},{"name":"Seven Mile Bridge","rarity":"common","id":"seven-mile-bridge","subtitle":"Bridge","details":"Florida's Seven Mile Bridge, opened in 1982, carries the Overseas Highway across open water in the Keys between Knight's Key and Little Duck Key.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Seven_mile_bridge.jpg/1280px-Seven_mile_bridge.jpg"},{"name":"Penang Bridge","rarity":"common","id":"penang-bridge","subtitle":"Bridge","details":"Malaysia's Penang Bridge, opened in 1985, links the island of Penang to the mainland across the Penang Strait, a dual carriageway about 13.5 kilometres long.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Penang_Bridge_Dec2024-1.jpg/1280px-Penang_Bridge_Dec2024-1.jpg"},{"name":"Prince of Wales Bridge","rarity":"common","id":"prince-of-wales-bridge","subtitle":"Bridge","details":"The Prince of Wales Bridge, opened in 1996 as the Second Severn Crossing, carries the M4 motorway over the River Severn between England and Wales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Prince%20of%20Wales%20Bridge%20%28M4%29%20%28Oscar%20Taylor%29%20-%20Geograph.jpg?width=1024"},{"name":"Moon Bridge (Taipei)","rarity":"common","id":"moon-bridge","subtitle":"Bridge","details":"Taipei's Moon Bridge crosses the lake in Dahu Park, a traditional Chinese-style arched footbridge whose reflection completes a full circle in the water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jindai%20Bridge%20reflected%20in%20water%20at%20night%20on%2026%20December%202015.jpg?width=1024"},{"name":"Woolworth Building","rarity":"common","id":"woolworth-building","subtitle":"Skyscraper","details":"New York's Woolworth Building, completed in 1913, is a neo-Gothic skyscraper clad in terracotta and nicknamed the Cathedral of Commerce for its grand lobby.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Woolworth%20bldg%20nov2005c.jpg?width=800"},{"name":"Tribune Tower","rarity":"common","id":"tribune-tower","subtitle":"Tower","details":"Chicago's Tribune Tower, completed in 1925, is a neo-Gothic tower whose walls embed stones from famous sites worldwide, from the Great Wall to the Parthenon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tribune_Tower%2C_Chicago%2C_Illinois_%289181667444%29_%28cropped%29.jpg?width=800"},{"name":"Wrigley Building","rarity":"common","id":"wrigley-building","subtitle":"Skyscraper","details":"Chicago's Wrigley Building, completed in 1924, is a white terracotta tower across the Chicago River, floodlit at night and clad in six shades of glazed brick.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wrigley_Building_1_%2831887261212%29.jpg?width=1024"},{"name":"Aon Center","rarity":"common","id":"aon-center","subtitle":"Skyscraper","details":"Chicago's Aon Center, completed in 1973, is a 346-metre slab of white granite whose original marble cladding was fully replaced after panels began to bow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aon_Center_in_Chicago_May_2016.jpg?width=1024"},{"name":"Bank of America Plaza (Atlanta)","rarity":"common","id":"bank-of-america-plaza-atlanta","subtitle":"Skyscraper","details":"Atlanta's Bank of America Plaza, completed in 1992, is a 317-metre Art Deco-style tower whose spire glows amber and tapers like a finely sharpened pencil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BOA_Plaza_ATL_GA.jpg?width=800"},{"name":"U.S. Bank Tower (Los Angeles)","rarity":"common","id":"us-bank-tower-los-angeles","subtitle":"Tower","details":"The U.S. Bank Tower in Los Angeles, completed in 1989, is a 310-metre cylindrical tower topped by a glass crown, built to withstand strong earthquakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Citibank%20Center%2C%20US%20Bank%20Tower%20and%20The%20Gas%20Company%20Tower.jpg?width=1024"},{"name":"JPMorgan Chase Tower (Houston)","rarity":"common","id":"jpmorgan-chase-tower-houston","subtitle":"Tower","details":"Houston's JPMorgan Chase Tower, completed in 1982, is a 305-metre tower of grey granite and glass, unique in the city for its unusual five-sided floor plan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JP_Morgan_Chase_Tower_in_Houston_2_-_Dec_2013_%28cropped%29.JPG?width=1024"},{"name":"Wells Fargo Plaza","rarity":"common","id":"wells-fargo-plaza","subtitle":"Skyscraper","details":"Houston's Wells Fargo Plaza, completed in 1983, is a 302-metre tower wrapped entirely in glass, with a stepped, cascading profile on its north and south faces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wells%20Fargo%20Plaza%20Houston%20TX%202014%2008%2003%2003.jpg?width=1024"},{"name":"The Gherkin","rarity":"common","id":"the-gherkin","subtitle":"Skyscraper","details":"London's Gherkin, officially 30 St Mary Axe and completed in 2004, is a 180-metre bullet-shaped tower whose swirling glass skin hides a diagrid steel frame.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/30_St_Mary_Axe%2C_%27Gherkin%27.JPG?width=800"},{"name":"20 Fenchurch Street","rarity":"common","id":"20-fenchurch-street","subtitle":"Skyscraper","details":"London's 20 Fenchurch Street, completed in 2014, flares outward as it rises to 160 metres, earning its Walkie-Talkie nickname from its top-heavy silhouette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Walkie-Talkie_-_Sept_2015_%28cropped%29.jpg?width=1024"},{"name":"Leadenhall Building","rarity":"common","id":"leadenhall-building","subtitle":"Skyscraper","details":"London's Leadenhall Building, completed in 2014, leans back in a tapering wedge nicknamed the Cheesegrater, angled to protect views of St Paul's Cathedral.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cheesegrater_and_Gherkin.jpg?width=1024"},{"name":"Commerzbank Tower","rarity":"common","id":"commerzbank-tower","subtitle":"Tower","details":"Frankfurt's Commerzbank Tower, completed in 1997, rises 259 metres around a full-height atrium, with sky gardens cut into a different side every four floors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frankfurt_Commerzbank-Turm.20130904.jpg?width=1024"},{"name":"Messeturm","rarity":"common","id":"messeturm","subtitle":"Skyscraper","details":"Frankfurt's Messeturm, completed in 1990, is a 257-metre red sandstone tower capped by a pyramid, a landmark of the city's fair and festival grounds area.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frankfurt_am_Main%2C_MesseTurm.jpg?width=800"},{"name":"Marina City","rarity":"common","id":"marina-city","subtitle":"Skyscraper","details":"Chicago's Marina City, completed in 1968, pairs two 179-metre corncob-shaped residential towers with petal-like balconies above a marina on the Chicago River.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marina_City%2C_Chicago%2C_Illinois%2C_Estados_Unidos%2C_2012-10-20%2C_DD_01.jpg?width=1024"},{"name":"Aqua Tower","rarity":"common","id":"aqua-tower","subtitle":"Tower","details":"Chicago's Aqua Tower, completed in 2009, is a 262-metre tower whose wave-like white balconies ripple across the facade, designed by architect Jeanne Gang.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2020-01-01%204904x7356%20chicago%20aqua.jpg?width=1024"},{"name":"Absolute World Towers","rarity":"common","id":"absolute-world-towers","subtitle":"Tower","details":"Mississauga's Absolute World Towers, completed in 2012, are twin residential towers that twist continuously from base to top, nicknamed the Marilyn Towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Absolute_Towers_Mississauga._South-west_view.jpg?width=1024"},{"name":"Torre Iberdrola","rarity":"common","id":"torre-iberdrola","subtitle":"Skyscraper","details":"Bilbao's Torre Iberdrola, completed in 2011, is a 165-metre triangular glass tower of offices standing in the Abandoibarra district beside the River Nervion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Iberdrola_Tower_2019.jpg?width=1024"},{"name":"Istanbul Sapphire","rarity":"common","id":"istanbul-sapphire","subtitle":"Skyscraper","details":"Istanbul Sapphire, completed in 2010, is a 261-metre residential tower with sky gardens stacked behind a double glass facade above the Levent district.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Istanbul_Sapphire_02.jpg?width=800"},{"name":"Heron Tower","rarity":"common","id":"heron-tower","subtitle":"Tower","details":"London's Heron Tower, completed in 2011, is a 230-metre office tower on Bishopsgate whose lobby holds an enormous aquarium stocked with tropical fish.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heron_Tower%2C_Bishopsgate%2C_London.JPG?width=800"},{"name":"Duke Energy Center","rarity":"common","id":"duke-energy-center","subtitle":"Skyscraper","details":"Charlotte's Duke Energy Center, completed in 2010, is a 240-metre tower with a distinctive notched crown lit in changing colours above the city at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Duke%20Energy%20Center.jpg?width=1024"},{"name":"Franklin Center","rarity":"common","id":"franklin-center","subtitle":"Skyscraper","details":"Chicago's Franklin Center, completed in 1989, is a 307-metre red-granite tower with twin spires, built as the AT&T Corporate Center on South Franklin Street.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20120929_Franklin_Center.JPG?width=1024"},{"name":"Two Prudential Plaza","rarity":"common","id":"two-prudential-plaza","subtitle":"Skyscraper","details":"Chicago's Two Prudential Plaza, completed in 1990, is a 303-metre tower whose chevron facade and tall spire form a modern take on classic Art Deco setbacks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Two%20Prudential%20Plaza.jpg?width=1024"},{"name":"Bank of America Tower (New York)","rarity":"common","id":"bank-of-america-tower-new-york","subtitle":"Tower","details":"New York's Bank of America Tower, completed in 2009, is a 366-metre glass tower at One Bryant Park, built with recycled materials and ice-storage cooling.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bank_of_America_Tower_-_2025_%2854821833478%29.jpg?width=800"},{"name":"One57","rarity":"common","id":"one57","subtitle":"Skyscraper","details":"New York's One57, completed in 2014, is a 306-metre residential tower on Billionaires' Row whose rippled blue-glass facade overlooks Central Park below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/One57%20New%20York%20in%202015.jpg?width=1024"},{"name":"8 Spruce Street","rarity":"common","id":"8-spruce-street","subtitle":"Skyscraper","details":"New York's 8 Spruce Street, designed by Frank Gehry and completed in 2011, is a 265-metre tower wrapped in a rippling stainless-steel skin of bay windows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/8%20Spruce%20Street%20%2801030p%29.jpg?width=800"},{"name":"Torre Costanera","rarity":"common","id":"torre-costanera","subtitle":"Skyscraper","details":"Santiago's Torre Costanera, completed in 2013, is a 300-metre glass tower in the Costanera Center complex, the centrepiece of the Providencia skyline.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Costanera_Center_at_evening_%28cropped%29.jpg?width=800"},{"name":"Blarney Castle","rarity":"common","id":"blarney-castle","subtitle":"Castle","details":"Cormac MacCarthy built this stone stronghold near Cork in 1446; kissing its Blarney Stone, set in the battlements, is said in legend to grant eloquence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blarney_Castle_Ireland.jpg?width=1024"},{"name":"Bunratty Castle","rarity":"common","id":"bunratty-castle","subtitle":"Castle","details":"This County Clare tower house of about 1425 stands beside a folk park, its great hall restored with medieval furnishings, tapestries and banquets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bunrattybig.jpg?width=1024"},{"name":"Cardiff Castle","rarity":"common","id":"cardiff-castle","subtitle":"Castle","details":"Within Roman and Norman fortifications in the Welsh capital, the Bute family created a Victorian Gothic fantasy of richly decorated towers and themed interiors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cardiff%20Castle%20-%20Clock%20Tower%20-%20geograph.org.uk%20-%205253121.jpg?width=1024"},{"name":"Inveraray Castle","rarity":"common","id":"inveraray-castle","subtitle":"Castle","details":"Seat of the dukes of Argyll on Loch Fyne, this conical-towered castle of the 1740s was an early Gothic Revival house, rebuilt after a fire in 1877.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Inveraray_Castle_-_south-west_facade.jpg?width=1024"},{"name":"Urquhart Castle","rarity":"common","id":"urquhart-castle","subtitle":"Castle","details":"These romantic ruins on Loch Ness guarded the Great Glen for centuries; the surviving Grant Tower watches the water of Nessie legend above the shore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Urquhart_Castle_Tower_House_2.jpg?width=1024"},{"name":"Glamis Castle","rarity":"common","id":"glamis-castle","subtitle":"Castle","details":"The Lyon family home in Angus since 1372, Glamis grew from a hunting lodge into a turreted Scottish baronial castle and a childhood home of Queen Elizabeth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Glamis_Castle_-_geograph.org.uk_-_7848853.jpg?width=1024"},{"name":"Scone Palace","rarity":"common","id":"scone-palace","subtitle":"Palace","details":"Scottish kings were crowned at Scone for centuries beside the Stone of Destiny; the present Gothic palace of red sandstone rose in the early nineteenth century.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Perth_and_Kinross_Scone_Palace_2.jpg?width=1024"},{"name":"Holyrood Palace","rarity":"common","id":"holyrood-palace","subtitle":"Palace","details":"The monarch's Edinburgh residence grew from a 1128 abbey guesthouse at the foot of Arthur's Seat; Mary, Queen of Scots lived in its turreted tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Holyrood_Palace_-_aerial_-_2025-04-19_01_%28cropped%29.jpg?width=1024"},{"name":"Kensington Palace","rarity":"common","id":"kensington-palace","subtitle":"Palace","details":"William and Mary bought this London mansion in 1689 and Christopher Wren remodelled it as a royal residence, later the childhood home of Queen Victoria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kensington_Palace%2C_the_South_Front_-_geograph.org.uk_-_287402.jpg?width=1024"},{"name":"Hampton Court Palace","rarity":"common","id":"hampton-court-palace","subtitle":"Palace","details":"Cardinal Wolsey's Tudor palace on the Thames was seized by Henry VIII, who added the great hall; Wren later built Baroque apartments for William and Mary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hampton_Court_Palace%2C_Base_Court%2C_Main_Entrance_Tower%2C_Richmond_upon_Thames_1193127_20230823_0072.jpg?width=1024"},{"name":"Blenheim Palace","rarity":"common","id":"blenheim-palace","subtitle":"Palace","details":"Parliament gave this Oxfordshire palace to the Duke of Marlborough after his 1704 Blenheim victory; Vanbrugh's Baroque masterpiece was Churchill's birthplace.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blenheim%20Palace%20cropped.jpg?width=1024"},{"name":"Chatsworth House","rarity":"common","id":"chatsworth-house","subtitle":"House","details":"Seat of the dukes of Devonshire, this Derbyshire house earned the name Palace of the Peak for its Baroque south front, painted halls and vast landscaped park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chatsworth_house_fountain_frontage.jpg?width=1024"},{"name":"Castle Howard","rarity":"common","id":"castle-howard","subtitle":"House","details":"Vanbrugh's first great house, begun in 1699 in Yorkshire, crowned English Baroque with a dramatic central dome, temples and follies across a vast estate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle_Howard_and_garden.jpg?width=1024"},{"name":"Eltz Castle","rarity":"common","id":"eltz-castle","subtitle":"Castle","details":"Burg Eltz has stood in a wooded Moselle valley for over 850 years, owned by one family throughout, its eight towers rising above a bend of the Elzbach stream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Le_ch%C3%A2teau_d%27Eltz_%28Burg_Eltz%29_en_allemagne_%28cropped%29.jpg?width=800"},{"name":"Lichtenstein Castle (Germany)","rarity":"common","id":"lichtenstein-castle-germany","subtitle":"Castle","details":"Inspired by Wilhelm Hauff's novel, this neo-Gothic castle of 1842 clings to a cliff edge in the Swabian Alps above the Echaz valley near Honau in Wurttemberg.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schloss_Lichtenstein_04-2010.jpg?width=1024"},{"name":"Miramare Castle","rarity":"common","id":"miramare-castle","subtitle":"Castle","details":"Archduke Ferdinand Maximilian built this white castle on the Gulf of Trieste in the 1850s, before he left to become emperor of Mexico in the 1860s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trieste_-_castello_di_Miramare_-_202209132345.jpeg?width=1024"},{"name":"Predjama Castle","rarity":"common","id":"predjama-castle","subtitle":"Castle","details":"This Slovenian castle is wedged into the mouth of a vast cave beneath a 123-metre cliff, linked in legend to the robber knight Erazem and his secret tunnels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/H%C3%B6hlenburg_Predjama_in_Slovenien.jpg?width=1024"},{"name":"Orava Castle","rarity":"common","id":"orava-castle","subtitle":"Castle","details":"Perched on a sheer rock above the Orava River in Slovakia, this thirteenth-century fortress climbs in tiers and appeared as Count Orlok's castle in Nosferatu.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oravsk%C3%BD_hrad_%28celkov%C3%BD_pohled%29.jpg?width=1024"},{"name":"Bojnice Castle","rarity":"common","id":"bojnice-castle","subtitle":"Castle","details":"Count Jan Palffy rebuilt this Slovak castle in the 1890s in romantic French Gothic style, its blue-roofed turrets rising above a park and a travertine cave.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bojnice_%28Bojnitz%29_Castle_%28by_Pudelek%29.jpg?width=1024"},{"name":"Spis Castle","rarity":"common","id":"spis-castle","subtitle":"Castle","details":"Among the largest castle ruins in Central Europe, this Slovak stronghold of the 1100s sprawls across a travertine hill with sweeping countryside views.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spis%20panorama.jpg?width=1024"},{"name":"Trakai Island Castle","rarity":"common","id":"trakai-island-castle","subtitle":"Castle","details":"The dukes of Lithuania built this red-brick Gothic castle on an island in Lake Galve in the 1400s, a lakeside fortress restored to its medieval splendour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Traku_pilis_by_Augustas_Didzgalvis.jpg?width=1024"},{"name":"Frederiksborg Castle","rarity":"common","id":"frederiksborg-castle","subtitle":"Castle","details":"Christian IV built Denmark's largest Renaissance castle on three islets in Hillerod in the early 1600s, its copper spires reflected in the castle lake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frederiksborg_Castle_and_boat_crop.jpg?width=1024"},{"name":"Rosenborg Castle","rarity":"common","id":"rosenborg-castle","subtitle":"Castle","details":"Christian IV built this Dutch Renaissance castle in Copenhagen in 1606 as a summer house; its treasury guards the Danish crown jewels and coronation thrones.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/I12_174_Schloss_Rosenborg.jpg?width=1024"},{"name":"Amalienborg","rarity":"common","id":"amalienborg","subtitle":"Palace","details":"Four identical rococo palaces frame an octagonal Copenhagen square, home of the Danish royal family since 1794 and watched over by mounted royal life guards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amalienborg_Palace_%28cropped%29.jpg?width=1024"},{"name":"Drottningholm Palace","rarity":"common","id":"drottningholm-palace","subtitle":"Palace","details":"Sweden's royal residence on Lovon island began in the 1660s in French Baroque style, preserving a working eighteenth-century court theatre and Chinese pavilion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Drottningholm%20Palace%20%28by%20Pudelek%29%201.jpg?width=1024"},{"name":"Gripsholm Castle","rarity":"common","id":"gripsholm-castle","subtitle":"Castle","details":"Gustav Vasa founded this red-brick Renaissance castle on Lake Malaren in 1537; its round towers guard Sweden's national portrait collection of over 5,000 works.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gripsholms_slott_view2.jpg?width=1024"},{"name":"Hohenwerfen Castle","rarity":"common","id":"hohenwerfen-castle","subtitle":"Castle","details":"This hilltop fortress above Austria's Salzach valley dates from 1075, guarding a mountain pass with mighty walls, a falconry centre and film-famous ramparts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hohenwerfen_castle.jpg?width=1024"},{"name":"Craigievar Castle","rarity":"common","id":"craigievar-castle","subtitle":"Castle","details":"Completed in 1626 in Aberdeenshire, this pink-harled Scottish tower house of seven storeys is a fairytale of turrets with almost no later alteration.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Craigievar_Doocot_and_Castle_-_geograph.org.uk_-_7846018.jpg?width=1024"},{"name":"Knossos","rarity":"common","id":"knossos","subtitle":"Ancient Site","details":"The largest palace of Bronze Age Crete, Knossos was the centre of Minoan civilisation, its labyrinth of rooms rebuilt around 1700 BC after an earthquake.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Knossos%20north%20entrance%2C%20Crete%20001.JPG?width=1024"},{"name":"Mycenae","rarity":"common","id":"mycenae","subtitle":"Ancient Site","details":"A fortified Bronze Age citadel in Greece, Mycenae's massive Cyclopean walls and Lion Gate guarded a warrior kingdom that flourished around 1250 BC.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Path_upto_the_Lion_Gate%2C_Mycenae_%2828693130016%29.jpg?width=1024"},{"name":"Olympia","rarity":"common","id":"olympia","subtitle":"Ancient Site","details":"In Greece's Peloponnese, Olympia hosted the ancient Olympic Games from 776 BC, its sanctuaries holding temples of Zeus and Hera and a great stadium.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Olympia%2C_Greece2.jpg?width=1024"},{"name":"Delphi","rarity":"common","id":"delphi","subtitle":"Ancient Site","details":"On the slopes of Mount Parnassus, Delphi was the sanctuary of Apollo where the Pythia delivered oracles, ringed by temples, treasuries and a theatre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Delphi%2C_Greece_-_panoramio.jpg?width=1024"},{"name":"Delos","rarity":"common","id":"delos","subtitle":"Ancient Site","details":"A sacred Greek island in the Aegean, Delos was the mythical birthplace of Apollo and Artemis and a wealthy trading port of temples and merchants' houses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Delos_general.jpg?width=800"},{"name":"Akrotiri","rarity":"common","id":"akrotiri","subtitle":"Ancient Site","details":"A Minoan town on Santorini buried by a volcanic eruption around 1600 BC, Akrotiri preserves multi-storey houses and vivid frescoes beneath the ash.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ancient_Akrotiri.jpeg?width=1024"},{"name":"Phaistos","rarity":"common","id":"phaistos","subtitle":"Ancient Site","details":"A Minoan palace on Crete's Messara Plain, Phaistos rose around 1900 BC with grand courts and staircases, and yielded the famed inscribed Phaistos Disc.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Central%20courtyard%20Phaistos%20palace%20Crete.jpg?width=1024"},{"name":"Troy","rarity":"common","id":"troy","subtitle":"Ancient Site","details":"Layer upon layer of Bronze Age walls at Hisarlik in Turkey mark Troy, the city sung in Homer's Iliad and besieged, in legend, over the abduction of Helen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Walls_of_Troy_%282%29.jpg?width=1024"},{"name":"Pergamon","rarity":"common","id":"pergamon","subtitle":"Ancient Site","details":"A Hellenistic royal capital in Turkey, Pergamon crowned its steep acropolis with temples, a library and a theatre carved into the hillside around 200 BC.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acropolis_-_Bergama_%28Pergamon%29_-_Turkey_-_10_%285747249729%29.jpg?width=1024"},{"name":"Aspendos Theatre","rarity":"common","id":"aspendos-theatre","subtitle":"Ancient Site","details":"Built in Roman Pamphylia around AD 155, the theatre at Aspendos in Turkey keeps its towering stage building, among the best preserved of the ancient world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aspendos%20Theatre%20-%20panoramio.jpg?width=1024"},{"name":"Hierapolis","rarity":"common","id":"hierapolis","subtitle":"Ancient Site","details":"A Roman spa city above Pamukkale's white travertine terraces in Turkey, Hierapolis drew the sick and wealthy to its hot springs, theatre and vast necropolis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hierapolis_01.jpg?width=1024"},{"name":"Djemila","rarity":"common","id":"djemila","subtitle":"Ancient Site","details":"A Roman mountain town in Algeria founded around AD 96, Djemila preserves a forum, temples, basilicas and a triumphal arch in finely dressed stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Roman_Ruins_of_Djemila_in_S%C3%A9tif%2C_Algeria.jpg?width=1024"},{"name":"Timgad","rarity":"common","id":"timgad","subtitle":"Ancient Site","details":"Founded in Algeria around AD 100 for Roman veterans, Timgad was laid out on a strict grid of streets with a theatre, forum and the Arch of Trajan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Timgad_%2815685889550%29.jpg?width=1024"},{"name":"Dougga","rarity":"common","id":"dougga","subtitle":"Ancient Site","details":"A Numidian and Roman city in Tunisia, Dougga climbs a hillside with a sandstone Capitol temple, theatre and streets overlooking olive plains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dougga%2C_Beja.jpg?width=1024"},{"name":"Great Zimbabwe","rarity":"common","id":"great-zimbabwe","subtitle":"Ancient Site","details":"Built of fitted granite blocks from the 11th century, Great Zimbabwe was the capital of a wealthy Shona kingdom trading gold as far as the Indian Ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Conical_Tower_-_Great_Enclosure_III_%2833736918448%29.jpg?width=1024"},{"name":"Joya de Ceren","rarity":"common","id":"joya-de-ceren","subtitle":"Ancient Site","details":"A Maya farming village in El Salvador buried by volcanic ash around AD 600, Joya de Ceren preserves adobe houses, stores and fields in remarkable detail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ES_Joya_Ceren_05_2012_Estructura_9_Area_2_Tamazcal_wide_angle_1479.JPG?width=1024"},{"name":"Copan","rarity":"common","id":"copan","subtitle":"Ancient Site","details":"A Maya city in Honduras famed for its carved stelae and the Hieroglyphic Stairway, Copan flourished as an artistic capital in the 5th to 9th centuries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hieroglyphic%20Stairway%20of%20Cop%C3%A1n%20and%20stela%20M%20%2840008952385%29.jpg?width=1024"},{"name":"Xochicalco","rarity":"common","id":"xochicalco","subtitle":"Ancient Site","details":"A fortified hilltop city near Cuernavaca that rose after Teotihuacan's fall, Xochicalco is famed for its Pyramid of the Plumed Serpent and carved reliefs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mexico_xochicalco_pyramids.JPG?width=1024"},{"name":"Diocletian's Palace","rarity":"common","id":"diocletians-palace","subtitle":"Ancient Site","details":"Built around AD 305 as the retirement palace of the Roman emperor Diocletian, this fortified seaside complex in Split, Croatia, became the city's old town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croatia-01239_-_The_Peristil_%289551533404%29.jpg?width=1024"},{"name":"Nuraghe Su Nuraxi","rarity":"common","id":"nuraghe-su-nuraxi","subtitle":"Ancient Site","details":"Built in Sardinia around 1500 BC, Su Nuraxi is a Bronze Age nuraghe of basalt towers and a village of circular stone huts raised by the Nuragic people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nuraghe%20Su%20Nuraxi%20-%20Barumini%20-%20Sardinia%20-%20Italy%20-%2007.jpg?width=1024"},{"name":"Sacsayhuaman","rarity":"common","id":"sacsayhuaman","subtitle":"Ancient Site","details":"Above Cusco in Peru, the Inca fortress of Sacsayhuaman was built in the 15th century from gigantic interlocking stone blocks fitted without mortar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sacsayhuam%C3%A1n%2C_Cusco%2C_Per%C3%BA%2C_2015-07-31%2C_DD_27.JPG?width=1024"},{"name":"Tiwanaku","rarity":"common","id":"tiwanaku","subtitle":"Ancient Site","details":"Near Lake Titicaca in Bolivia, Tiwanaku was a ceremonial capital from about AD 500, built of sandstone and andesite with the carved Gate of the Sun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PUERTA_DEL_SOL_TIWANAKU.jpg?width=1024"},{"name":"Chan Chan","rarity":"common","id":"chan-chan","subtitle":"Ancient Site","details":"Built of adobe near Trujillo around AD 850, Chan Chan was the capital of the Chimu kingdom and the largest pre-Columbian adobe city in the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chan_chan_view1.jpg?width=1024"},{"name":"Monte Alban","rarity":"common","id":"monte-alban","subtitle":"Ancient Site","details":"Founded around 500 BC on a flattened hilltop in Oaxaca, Monte Alban was a Zapotec capital of pyramids, ballcourts and tombs overlooking three valleys.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monte_Alban_West_Side_Platform.jpg?width=1024"},{"name":"Habitat 67","rarity":"common","id":"habitat-67","subtitle":"Building","details":"Moshe Safdie's Montreal housing complex, built for Expo 67, stacks 354 prefabricated concrete boxes into a terraced hill of homes and gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Habitat%2067%202019%20dllu%2002.jpg?width=1024"},{"name":"Nakagin Capsule Tower","rarity":"common","id":"nakagin-capsule-tower","subtitle":"Building","details":"Kisho Kurokawa's Tokyo tower, completed in 1972, bolted 140 capsules to two concrete cores as a manifesto of Metabolism; it was demolished in 2022.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nakagin.jpg?width=800"},{"name":"CCTV Headquarters","rarity":"common","id":"cctv-headquarters","subtitle":"Building","details":"Rem Koolhaas's Beijing headquarters for China Central Television, completed in 2012, forms a continuous loop of two leaning towers joined at the top.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rem%20Koolhaas%20CCTV%20building%20%286233587191%29.jpg?width=1024"},{"name":"Seattle Public Library","rarity":"common","id":"seattle-public-library","subtitle":"Library","details":"Rem Koolhaas's Seattle Central Library, opened in 2004, stacks its floors as offset glass boxes wrapped in a diamond-pattern steel grid.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seattle%20Central%20Library%20exterior%20-%20Flickr%20-%20brewbooks.jpg?width=1024"},{"name":"Geisel Library","rarity":"common","id":"geisel-library","subtitle":"Library","details":"This eight-storey library at UC San Diego, completed in 1970 and later named for Theodor Geisel, rises like a lantern of glass above a concrete base.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/UC%20San%20Diego%20Geisel%20Library.jpg?width=1024"},{"name":"Robie House","rarity":"common","id":"robie-house","subtitle":"House","details":"Frank Lloyd Wright's Robie House in Chicago, completed in 1910, stretches long horizontal roofs and ribbons of art glass across its brick Prairie form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Robie%20House%20%28Frank%20Lloyd%20Wright%29%20-%20Chicago%20IL%20%287839623548%29.jpg?width=1024"},{"name":"Villa Savoye","rarity":"common","id":"villa-savoye","subtitle":"House","details":"Le Corbusier's Villa Savoye, completed in 1931 near Paris, lifts a white box on slim pilotis as a manifesto of the modern movement in architecture.","image":"https://thumb.wikimedia.org/wikipedia/fr/thumb/9/98/Villa_Savoye_en_2014.jpg/1280px-Villa_Savoye_en_2014.jpg"},{"name":"Farnsworth House","rarity":"common","id":"farnsworth-house","subtitle":"House","details":"Mies van der Rohe's glass-walled house in Illinois, completed in 1951, floats between eight white steel columns above the Fox River floodplain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Farnsworth%20House%20Exterior%202.jpg?width=1024"},{"name":"The Glass House","rarity":"common","id":"the-glass-house","subtitle":"House","details":"Philip Johnson built this glass-walled house in New Canaan, Connecticut in 1949, setting it as a transparent pavilion in a landscaped estate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philip%20Johnson%20Glass%20House%20The%20House.jpg?width=1024"},{"name":"Seagram Building","rarity":"common","id":"seagram-building","subtitle":"Building","details":"Mies van der Rohe's Seagram Building, completed in 1958 on Park Avenue in New York, set the pattern for bronze-and-glass office towers worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seagram%20Building-NewYork-3.jpg?width=1024"},{"name":"Lever House","rarity":"common","id":"lever-house","subtitle":"Building","details":"Completed in 1952 across Park Avenue from the Seagram site, Lever House raised one of New York's first glass curtain-wall office towers on a low podium.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lever%20House%20390%20Park%20Avenue.jpg?width=1024"},{"name":"Union Station (Washington)","rarity":"common","id":"union-station-washington","subtitle":"Station","details":"Daniel Burnham's Beaux-Arts Union Station in Washington, opened in 1907, fronts the Capitol with a long granite facade and triumphal arches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Front%20of%20Union%20Station%20Washington%20DC%202026-07-23%2014-47-31.jpg?width=1024"},{"name":"Musee d'Orsay","rarity":"common","id":"musee-dorsay","subtitle":"Building","details":"Housed in a Beaux-Arts railway station opened for the 1900 Paris fair, this museum displays its art beneath a great barrel-vaulted glass roof.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MuseeDOrsay.jpg?width=1024"},{"name":"Kanazawa Station","rarity":"common","id":"kanazawa-station","subtitle":"Station","details":"Kanazawa's station in Japan greets travellers with the wooden Tsuzumimon gate and a sweeping glass dome, opened together in the station's 2005 rebuild.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tsuzumimon%20Gate%20in%20front%20of%20Kanazawa%20Station%2020150120.JPG?width=1024"},{"name":"Helsinki Central Station","rarity":"common","id":"helsinki-central-station","subtitle":"Station","details":"Eliel Saarinen's Helsinki station, opened in 1919 in granite National Romantic style, is guarded by four stone giants holding spherical lamps.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Helsinki%20Central%20Station%20fa%C3%A7ade.jpg?width=1024"},{"name":"Oslo Opera House","rarity":"common","id":"oslo-opera-house","subtitle":"Building","details":"Opened in 2008 in Oslo's harbour, this opera house rises from the fjord as an angled white marble slope that visitors can walk across to the roof.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oslo%20Opera%20house%20exterior%20in%202010.jpg?width=1024"},{"name":"Denver Art Museum","rarity":"common","id":"denver-art-museum","subtitle":"Museum","details":"Daniel Libeskind's Hamilton Building, opened in 2006 in Denver, juts in titanium-clad shards modelled on the peaks of the Rocky Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Denver%20Art%20Museum%20%2854940752080%29.jpg?width=1024"},{"name":"Milwaukee Art Museum","rarity":"common","id":"milwaukee-art-museum","subtitle":"Museum","details":"Santiago Calatrava's pavilion on Lake Michigan, opened in 2001, opens a vast movable sunshade of fin-like wings above the Milwaukee Art Museum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milwaukee%20Art%20Museum%201%20%28Mulad%29.jpg?width=1024"},{"name":"Rock and Roll Hall of Fame","rarity":"common","id":"rock-and-roll-hall-of-fame","subtitle":"Museum","details":"I. M. Pei's Rock and Roll Hall of Fame, opened in 1995 on the Lake Erie shore in Cleveland, sets a glass pyramid against a 162-foot tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rock%20and%20Roll%20Hall%20of%20Fame%2C%20May%202016.jpg?width=1024"},{"name":"Museum of Pop Culture","rarity":"common","id":"museum-of-pop-culture","subtitle":"Museum","details":"Frank Gehry's Museum of Pop Culture in Seattle, opened in 2000 at the foot of the Space Needle, swirls in coloured metal panels cut by a monorail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monorail%20tracks%20enter%20EMP-SFM%2002.jpg?width=1024"},{"name":"Bibliotheca Alexandrina","rarity":"common","id":"bibliotheca-alexandrina","subtitle":"Library","details":"Opened in 2002 beside Alexandria's harbour in Egypt, this library tilts a vast disc toward the sea, its granite wall carved with letters of many scripts.","image":"https://thumb.wikimedia.org/wikipedia/en/thumb/5/5e/Alexandria%27s_Bibliotheca.jpg/1280px-Alexandria%27s_Bibliotheca.jpg"},{"name":"National Stadium (Beijing)","rarity":"common","id":"national-stadium","subtitle":"Stadium","details":"Beijing's National Stadium, built for the 2008 Olympic Games, wraps its bowl in a web of steel beams that earned it the nickname the Bird's Nest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beijing%20national%20stadium.jpg?width=1024"},{"name":"Water Cube","rarity":"common","id":"water-cube","subtitle":"Building","details":"Beijing's National Aquatics Centre, built for the 2008 Olympics, is wrapped in blue bubble-like panels modelled on the geometry of soap foam.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lascar%20The%20Beijing%20National%20Aquatics%20Center%20%28Water%20Cube%29%20%284475631690%29.jpg?width=1024"},{"name":"London Aquatics Centre","rarity":"common","id":"london-aquatics-centre","subtitle":"Building","details":"Zaha Hadid's aquatics centre for the London 2012 Olympics sweeps a wave-like roof over its pools in the Queen Elizabeth Olympic Park at Stratford.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/London%20Aquatics%20Centre%20-%20Olympic%20Park.jpg?width=1024"},{"name":"Allianz Arena","rarity":"common","id":"allianz-arena","subtitle":"Stadium","details":"Opened in 2005 in Munich, this stadium wraps its bowl in air-filled panels that glow red, blue or white for the teams playing inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Allianz%20Arena%20%28Ank%20Kumar%20%2C%20Infosys%20Limited%29%2001.jpg?width=1024"},{"name":"Wembley Stadium","rarity":"common","id":"wembley-stadium","subtitle":"Stadium","details":"Rebuilt Wembley in London, opened in 2007 on the site of the 1923 original, is crowned by a 133-metre arch visible across the capital.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2023%20Challenge%20Cup%20Final%20Wembley%20Stadium%20from%20Olympic%20Way%2001.jpg?width=1024"},{"name":"Maracana Stadium","rarity":"common","id":"maracana-stadium","subtitle":"Stadium","details":"Rio de Janeiro's Maracana, opened for the 1950 World Cup, is a vast concrete oval overlooked by Corcovado and the statue of Christ the Redeemer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Est%C3%A1dio%20do%20Maracan%C3%A3%20%283345360655%29.jpg?width=1024"},{"name":"Camp Nou","rarity":"common","id":"camp-nou","subtitle":"Stadium","details":"FC Barcelona's Camp Nou, opened in 1957, is the largest football stadium in Europe, its steep tiers rising in the Les Corts district of the city.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Camp%20Nou%20in%20Barcelona.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
